package org.slavicmyths.verify.client;
import java.nio.file.*;import java.util.*;import java.util.concurrent.atomic.AtomicBoolean;
import net.minecraft.client.Minecraft;import net.minecraft.core.*;import net.minecraft.world.*;import net.minecraft.world.inventory.ClickType;import net.minecraft.world.item.*;import net.minecraft.world.level.*;import net.minecraft.world.level.block.*;import net.minecraft.world.phys.*;
import org.slavicmyths.kitchen.*;import org.slavicmyths.registry.ModBlocks;import org.slavicmyths.block.KitchenTableBlock;
/** Actual block-entity ticks and native client menu packets, supplied ingredients in one QA world. */
public final class Kitchen269 {
 static final boolean VISUAL=Boolean.getBoolean("slavicmyths.qa269.kitchenVisual");static final boolean RESTART=Boolean.getBoolean("slavicmyths.qa269.kitchenRestart");static final Path OUT=Path.of("../../docs/implementation/stabilization269-kitchen-20261026");
 static final BlockPos R=new BlockPos(1000,201,4),P=new BlockPos(1004,201,4);static final List<Map<String,Object>> checks=new ArrayList<>();static final Map<String,Object> out=new LinkedHashMap<>();static final AtomicBoolean queued=new AtomicBoolean();static final Set<String> shots=new HashSet<>();
 static boolean started,done;static int t,stage,wait,seen;static volatile int action;static long born=System.nanoTime(),lastGameTick=Long.MIN_VALUE;static KitchenTile rolling,pot;
 static Item item(String s){return KitchenII.item(s);}static void check(boolean ok,String text){checks.add(Map.of("status",ok?"PASS":"FAIL","test",text));System.out.println("QA269_KITCHEN "+(ok?"PASS ":"FAIL ")+text);if(!ok)throw new IllegalStateException(text);}
 static void finish(Throwable error){if(done)return;done=true;try{Files.createDirectories(OUT);out.put("checks",checks);out.put("status",error==null?"PASS_SINGLE_CLIENT_KITCHEN_SCOPE":"FAIL");out.put("error",error==null?null:error.toString());out.put("scope","one actual client/integrated server; native timer, supplied tools/ingredients; real menu packets; acquisition/MP NOT_RUN");Files.writeString(OUT.resolve((VISUAL?"visual":RESTART?"restart":"initial")+"-receipt.json"),new com.google.gson.GsonBuilder().setPrettyPrinting().create().toJson(out));if(error!=null)error.printStackTrace();}catch(Exception e){e.printStackTrace();}Minecraft.getInstance().stop();}
 static KitchenTile place(net.minecraft.server.level.ServerLevel w,BlockPos pos){var state=ModBlocks.KITCHEN_TABLE.get().defaultBlockState();w.setBlock(pos,state,2);w.setBlock(pos.east(),state.setValue(KitchenTableBlock.PART,KitchenTableBlock.Part.RIGHT),3);return (KitchenTile)w.getBlockEntity(pos);}
 static void setup(Minecraft mc)throws Exception{var server=mc.getSingleplayerServer();var w=server.overworld();var p=server.getPlayerList().getPlayers().getFirst();p.stopRiding();p.setGameMode(GameType.SURVIVAL);p.setNoGravity(true);p.teleportTo(w,1002.5,201,6.5,180,0);w.setChunkForced(62,0,true);w.getChunkAt(R);w.getChunkAt(P);
  if(VISUAL){rolling=(KitchenTile)w.getBlockEntity(R);pot=(KitchenTile)w.getBlockEntity(P);check(rolling!=null&&pot!=null,"visual repeat uses same physical saved stations");return;}if(!RESTART){p.getInventory().clearContent();for(int x=998;x<=1007;x++)for(int z=2;z<=7;z++)w.setBlock(new BlockPos(x,200,z),Blocks.STONE.defaultBlockState(),2);rolling=place(w,R);pot=place(w,P);rolling.inventory.setItem(2,new ItemStack(item("wheat_flour"),2));rolling.inventory.setItem(3,new ItemStack(Items.WATER_BUCKET));}
  else{rolling=(KitchenTile)w.getBlockEntity(R);pot=(KitchenTile)w.getBlockEntity(P);check(rolling!=null&&pot!=null,"both physical stations survive new client/server process");check(p.getInventory().countItem(item("dough"))==2,"taken dough inventory survives actual process restart");check(pot.inventory.getItem(2).isEmpty()&&pot.inventory.getItem(3).isEmpty(),"already consumed pot inputs stay consumed after restart");check(pot.inventory.getItem(7).is(Items.BUCKET)&&pot.inventory.getItem(7).getCount()==1,"exactly one water bucket remainder persisted");check(pot.busy()&&!pot.pending.isEmpty(),"actual in-progress pot recipe persisted, not NBT-only roundtrip");check(pot.total==160&&pot.pendingServings==3&&pot.activePot,"native time160 and pending three portions persisted");out.put("loaded_progress",pot.progress);}
 }
 static void server(Minecraft mc){try{var server=mc.getSingleplayerServer();var p=server.getPlayerList().getPlayers().getFirst();long now=server.overworld().getGameTime();if(now==lastGameTick)return;lastGameTick=now;if(t++==0){setup(mc);return;}
  if(VISUAL){if(t==20)action=3;if(t==60){check(p.containerMenu instanceof KitchenMenu,"corrected screen opens through real menu packet");mc.execute(()->finish(null));}return;}
  if(!RESTART){
   if(t==20){check(!rolling.busy()&&rolling.inventory.getItem(2).getCount()==2,"missing rolling pin prevents craft and consumption");rolling.inventory.setItem(0,new ItemStack(item("rolling_pin")));rolling.inventory.setItem(7,new ItemStack(Items.DIRT,64));rolling.inventory.setItem(8,new ItemStack(Items.DIRT,64));}
   if(t==40){check(!rolling.busy()&&rolling.inventory.getItem(2).getCount()==2,"blocked remainder slots prevent craft and consumption");rolling.inventory.setItem(7,ItemStack.EMPTY);rolling.inventory.setItem(8,ItemStack.EMPTY);}
   if(t==45){check(rolling.busy()&&rolling.total==80&&rolling.progress>0&&rolling.progress<80,"actual block ticks start native80tick rolling recipe");check(rolling.inventory.getItem(2).isEmpty()&&rolling.inventory.getItem(3).isEmpty(),"rolling inputs consumed once on start");check(rolling.inventory.getItem(7).is(Items.BUCKET)&&rolling.inventory.getItem(7).getCount()==1,"one empty bucket returned on start");check(rolling.inventory.getItem(6).isEmpty(),"output absent before native timer completion");rolling.removeTool(p,0);check(rolling.inventory.getItem(0).is(item("rolling_pin")),"busy rolling pin cannot be removed");}
   if(t==125){check(!rolling.busy()&&rolling.inventory.getItem(6).is(item("dough"))&&rolling.inventory.getItem(6).getCount()==2,"real80tick completion produces exactly two dough");check(rolling.inventory.getItem(0).getCount()==1,"rolling tool retained");action=1;}
   if(t==145){check(p.containerMenu instanceof KitchenMenu,"actual right-click packet opens KitchenMenu");action=2;}
   if(t==165){check(p.getInventory().countItem(item("dough"))==2&&rolling.inventory.getItem(6).isEmpty(),"real client quick-move takes output exactly once");p.closeContainer();pot.inventory.setItem(1,new ItemStack(item("metal_pot")));pot.inventory.setItem(2,new ItemStack(item("oat_groats"),2));pot.inventory.setItem(3,new ItemStack(Items.WATER_BUCKET));}
   if(t==200){check(pot.busy()&&pot.progress>0&&pot.progress<160,"stop while native160tick pot recipe is genuinely in progress");check(pot.servings==0&&pot.pendingServings==3,"three servings pending, no food prematurely available");out.put("saved_progress_before_stop",pot.progress);out.put("saved_total",pot.total);mc.execute(()->finish(null));}
   return;
  }
  if(stage==0){if(pot.busy())return;check(pot.servings==3&&pot.dish.is(item("oat_porridge")),"resumed native timer completes into exactly three portions");check(pot.inventory.getItem(7).getCount()==1,"resumed completion does not duplicate bucket");stage=1;wait=0;action=3;}
  else if(stage==1&&++wait==30){check(p.containerMenu instanceof KitchenMenu,"new client opens persisted pot station through packet");action=4;stage=2;wait=0;}
  else if(stage==2&&++wait==30){check(pot.servings==3&&p.getInventory().countItem(item("oat_porridge"))==0,"real serving button without bowl awards nothing");p.getInventory().setItem(8,new ItemStack(Items.BOWL,2));p.containerMenu.broadcastChanges();stage=3;wait=0;}
  else if(stage==3&&++wait==20){action=5;stage=4;wait=0;}
  else if(stage==4&&++wait==30){check(pot.servings==1&&p.getInventory().countItem(item("oat_porridge"))==2&&p.getInventory().countItem(Items.BOWL)==0,"three real button packets with two bowls give exactly two portions");check(pot.toolLocked(1),"pot remains locked while one serving remains");p.getInventory().setItem(8,new ItemStack(Items.BOWL));p.containerMenu.broadcastChanges();stage=5;wait=0;}
  else if(stage==5&&++wait==20){action=6;stage=6;wait=0;}
  else if(stage==6&&++wait==30){check(pot.servings==0&&pot.dish.isEmpty()&&p.getInventory().countItem(item("oat_porridge"))==3,"last bowl gives third portion and clears prepared dish");check(!pot.toolLocked(1),"empty pot tool unlocks");action=7;stage=7;wait=0;}
  else if(stage==7&&++wait==40){check(pot.servings==0&&p.getInventory().countItem(item("oat_porridge"))==3,"repeated serving after exhaustion cannot duplicate food");check(pot.inventory.getItem(7).getCount()==1&&pot.inventory.getItem(2).isEmpty(),"no repeated recipe or remainder after exhaustion");mc.execute(()->finish(null));}
 }catch(Throwable e){mc.execute(()->finish(e));}finally{queued.set(false);}}
 public static void tick(Minecraft mc){if(done||mc.player==null||mc.getSingleplayerServer()==null)return;try{if(!started){started=true;out.put("master_volume",mc.options.getSoundSourceOptionInstance(net.minecraft.sounds.SoundSource.MASTER).get());out.put("fps_limit",mc.options.framerateLimit().get());out.put("render_distance",mc.options.renderDistance().get());out.put("available_processors",Runtime.getRuntime().availableProcessors());out.put("max_heap_bytes",Runtime.getRuntime().maxMemory());out.put("GLFW_visible",org.lwjgl.glfw.GLFW.glfwGetWindowAttrib(mc.getWindow().getWindow(),org.lwjgl.glfw.GLFW.GLFW_VISIBLE));}
  if(System.nanoTime()-born>180_000_000_000L)throw new IllegalStateException("kitchen test timeout stage="+stage+" tick="+t);
  if(queued.compareAndSet(false,true))mc.getSingleplayerServer().execute(()->server(mc));int n=action;if(n<=seen)return;seen=n;
  if(n==1||n==3){var pos=n==1?R:P;mc.gameMode.useItemOn(mc.player,InteractionHand.MAIN_HAND,new BlockHitResult(Vec3.atCenterOf(pos),Direction.UP,pos,false));}
  else{check(mc.player.containerMenu instanceof KitchenMenu,"client received real synchronized KitchenMenu action"+n);if(n==2)mc.gameMode.handleInventoryMouseClick(mc.player.containerMenu.containerId,6,0,ClickType.QUICK_MOVE,mc.player);else for(int i=0;i<(n==5?3:1);i++)mc.gameMode.handleInventoryButtonClick(mc.player.containerMenu.containerId,0);}
 }catch(Throwable e){finish(e);}}
 public static void capture(Minecraft mc){if(VISUAL&&t<40)return;if(done||!(mc.player!=null&&mc.player.containerMenu instanceof KitchenMenu)||!shots.add("menu"+action))return;try{Files.createDirectories(OUT);try(var image=net.minecraft.client.Screenshot.takeScreenshot(mc.getMainRenderTarget())){image.writeToFile(OUT.resolve((VISUAL?"visual":RESTART?"restart":"initial")+"-menu"+action+".png"));}}catch(Exception e){finish(e);}}
}
